/*
 * Shared RTEMS entry point for the Splash-3 benchmarks.
 *
 * The number of worker threads is not fixed at build time: it is the number
 * of processors online at boot (e.g. `qemu -smp N`), capped by
 * SPLASH_MAX_PROCS.  Every "@P@" in the benchmark arguments and in the stdin
 * file name is replaced with that number.
 *
 * Per-benchmark settings come from rtems_args.h, generated by Makefile.config:
 *   BENCH_ARGV             comma-terminated list of argv strings
 *   BENCH_STDIN            optional file (in the rootfs) to use as stdin
 *   BENCH_ROOTFS           defined when a tar image is linked in (rootfs.S)
 *   BENCH_POW2_ONLY        defined when P must be a power of two
 *   BENCH_INIT_STACK_SIZE  optional stack size of the init thread
 */

#include <rtems.h>
#include <rtems/imfs.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "rtems_args.h"

#ifndef SPLASH_MAX_PROCS
#error "SPLASH_MAX_PROCS must be set by the build"
#endif

#ifdef BENCH_ROOTFS
extern const char rootfs_tar_start[];
extern const char rootfs_tar_end[];
#endif

int main(int argc, char **argv);

static int online_processors(void)
{
    rtems_id scheduler;
    cpu_set_t set;
    int n = 1;

    if (rtems_task_get_scheduler(RTEMS_SELF, &scheduler) == RTEMS_SUCCESSFUL &&
        rtems_scheduler_get_processor_set(scheduler, sizeof(set), &set) == RTEMS_SUCCESSFUL)
        n = CPU_COUNT(&set);

    return n < SPLASH_MAX_PROCS ? n : SPLASH_MAX_PROCS;
}

/* Returns a copy of `s` with every "@P@" replaced by `p`. */
static char *subst_procs(const char *s, int p)
{
    char num[12];
    int numlen = snprintf(num, sizeof(num), "%d", p);
    size_t len = strlen(s) + 1;
    const char *q;

    for (q = s; (q = strstr(q, "@P@")) != NULL; q += 3)
        len += numlen;

    char *out = malloc(len);
    char *o = out;
    if (out == NULL) {
        perror("malloc");
        exit(1);
    }

    while ((q = strstr(s, "@P@")) != NULL) {
        memcpy(o, s, q - s);
        o += q - s;
        memcpy(o, num, numlen);
        o += numlen;
        s = q + 3;
    }
    strcpy(o, s);
    return out;
}

void *POSIX_Init(void *arg)
{
    static const char *const args[] = { BENCH_ARGV };
    enum { NARGS = sizeof(args) / sizeof(args[0]) };
    char *argv[NARGS + 1];
    int p = online_processors();
    int i;

    (void)arg;

#ifdef BENCH_POW2_ONLY
    if ((p & (p - 1)) != 0) {
        fprintf(stderr, "%s: needs a power-of-two processor count, %d online\n",
                args[0], p);
        exit(1);
    }
#endif

    for (i = 0; i < NARGS; i++)
        argv[i] = subst_procs(args[i], p);
    argv[NARGS] = NULL;

    printf("%s: running on %d processor(s)\n", argv[0], p);

#ifdef BENCH_ROOTFS
    if (rtems_tarfs_load("/", (uint8_t *)rootfs_tar_start,
                         rootfs_tar_end - rootfs_tar_start) != 0) {
        perror("rtems_tarfs_load");
        exit(1);
    }
#endif

#ifdef BENCH_STDIN
    char *input = subst_procs(BENCH_STDIN, p);
    if (freopen(input, "r", stdin) == NULL) {
        perror(input);
        exit(1);
    }
#endif

    exit(main(NARGS, argv));
    return NULL;
}

/* Drivers needed */
#define CONFIGURE_APPLICATION_NEEDS_CONSOLE_DRIVER
#define CONFIGURE_APPLICATION_NEEDS_CLOCK_DRIVER

#ifdef BENCH_INIT_STACK_SIZE
#define CONFIGURE_POSIX_INIT_THREAD_STACK_SIZE BENCH_INIT_STACK_SIZE
#endif

/* POSIX configuration */
#define CONFIGURE_POSIX_APPLICATION
#define CONFIGURE_MAXIMUM_PROCESSORS SPLASH_MAX_PROCS
#define CONFIGURE_MAXIMUM_POSIX_THREADS SPLASH_MAX_PROCS
#define CONFIGURE_POSIX_INIT_THREAD_TABLE
#define CONFIGURE_USE_IMFS_AS_BASE_FILESYSTEM
#define CONFIGURE_MAXIMUM_FILE_DESCRIPTORS 32
#define CONFIGURE_INIT
#include <rtems/confdefs.h>
